llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C75"],
      "claim": "Glasdegib, a high-transfer analogue containing a nitrile and piperidine, had absolute oral bioavailability of 77.12% in healthy volunteers, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C59"],
      "claim": "Ampicillin, a zwitterionic amino acid with poor passive permeability, had absolute oral bioavailability of about 40% in humans, directly supporting that the query's zwitterionic character does not preclude F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Odanacatib, which contains a nitrile and fluorophenyl, had absolute oral bioavailability of 30% at a 50 mg fasted dose, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Setipiprant, a carboxylic acid-containing analogue with a fluorophenyl group, had human bioavailability of at least 50%, supporting high F despite acidic/zwitterionic features.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Maraviroc, a basic amine analogue with a fluorophenyl group, had absolute oral bioavailability of 23.1% (95% CI 19.2–27.8), supporting F ≥ 20% but with a narrower margin.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C74"],
      "claim": "Enzalutamide, containing a nitrile and fluorophenyl, had oral bioavailability of at least 84.2%, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "Meptazinol had low absolute oral bioavailability of 8.7 ± 1.6% in normal young male volunteers, attributed to extensive first-pass metabolism; this is the only low-F analogue and is contradictory, but its metabolic liability is not clearly shared by the query's zwitterionic acid scaffold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Multiple high-transfer experimental analogues show absolute oral bioavailability above the 20% threshold, including zwitterionic ampicillin (40%), acid/fluorophenyl setipiprant (≥50%), nitrile/fluorophenyl odanacatib (30%), and glasdegib (77%). The only low-F analogue, meptazinol, is low due to extensive first-pass metabolism, a liability not clearly shared by the query. Therefore the query is predicted to have high oral bioavailability (F ≥ 20%).",
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the query molecule.",
    "The query's zwitterionic permeability and possible transporter-mediated absorption are not experimentally characterized.",
    "Dose-dependent or solubility-limited absorption for the query has not been assessed.",
    "The extent of first-pass metabolism for the query is unknown."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

